import csv
import json
from datetime import datetime
from collections import defaultdict

# Read orders.csv
orders = []
with open('data/orders.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        orders.append(row)

# Read customers.json
with open('data/customers.json', 'r') as f:
    customers_list = json.load(f)
customers = {c['customer_id']: c for c in customers_list}

# Read adjustments.csv
adjustments = {}
with open('data/adjustments.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        adjustments[row['order_id']] = float(row['adjustment'])

# 1. parse_dates - parse order_date to extract month
def parse_date(date_str):
    formats = [
        '%m/%d/%Y',      # 01/27/2024
        '%Y-%m-%d',      # 2024-01-31
        '%d-%b-%Y',      # 02-Mar-2024
        '%d-%b-%Y',      # 14-Feb-2024
        '%b-%d-%Y',      # Mar-02-2024 (not seen but possible)
    ]
    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue
    # Try with lowercase
    for fmt in formats:
        try:
            return datetime.strptime(date_str.lower(), fmt.lower())
        except ValueError:
            continue
    raise ValueError(f"Cannot parse date: {date_str}")

for order in orders:
    order['parsed_date'] = parse_date(order['order_date'])
    order['month'] = order['parsed_date'].strftime('%Y-%m')
    order['updated_dt'] = datetime.fromisoformat(order['updated_at'])

# 2. filter_cancelled - remove cancelled orders
orders = [o for o in orders if o['status'] != 'cancelled']

# 3. deduplicate_latest - for same order_id, keep latest updated_at
order_dict = {}
for o in orders:
    oid = o['order_id']
    if oid not in order_dict or o['updated_dt'] > order_dict[oid]['updated_dt']:
        order_dict[oid] = o
orders = list(order_dict.values())

# 4. join_customers - add segment from customers
for order in orders:
    cust = customers.get(order['customer_id'])
    if cust:
        order['segment'] = cust['segment']
    else:
        order['segment'] = 'unknown'

# 5. apply_adjustments - add adjustment to amount
for order in orders:
    adj = adjustments.get(order['order_id'], 0)
    order['amount'] = float(order['amount']) + adj

# Group by month and segment
groups = defaultdict(lambda: {'order_count': 0, 'total_amount': 0.0})
for order in orders:
    key = (order['month'], order['segment'])
    groups[key]['order_count'] += 1
    groups[key]['total_amount'] += order['amount']

# Build output sorted by month, segment
result = []
for (month, segment), data in sorted(groups.items()):
    result.append({
        'month': month,
        'segment': segment,
        'order_count': data['order_count'],
        'total_amount': round(data['total_amount'], 2)
    })

# Write output
with open('outputs/report.json', 'w') as f:
    json.dump(result, f, indent=2)

print("Done!")
print(json.dumps(result, indent=2))
EOF", "session_id": 1}

