from collections import defaultdict

# Parse dates in various formats
def parse_date(date_str):
    formats = [
        "%Y-%m-%d",           # 2024-01-31
        "%m/%d/%Y",           # 01/27/2024
        "%d-%b-%Y",           # 02-Mar-2024
    ]
    for fmt in formats:
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            continue
    # Handle formats like "14-Feb-2024"
    if '-' in date_str:
        parts = date_str.split('-')
        if len(parts) == 3:
            day, month, year = parts
            try:
                return datetime.strptime(f"{day}-{month}-{year}", "%d-%b-%Y")
            except ValueError:
                pass
    raise ValueError(f"Could not parse date: {date_str}")

# Read orders.csv
orders = []
with open('/workspace/data/orders.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        orders.append(row)

# Parse dates
for order in orders:
    order['parsed_order_date'] = parse_date(order['order_date'])
    order['parsed_updated_at'] = datetime.fromisoformat(order['updated_at'])
    order['month'] = order['parsed_order_date'].strftime('%Y-%m')

# Filter cancelled
orders = [o for o in orders if o['status'] != 'cancelled']

# Deduplicate by order_id, keeping latest updated_at
order_dict = {}
for order in orders:
    oid = order['order_id']
    if oid not in order_dict or order['parsed_updated_at'] > order_dict[oid]['parsed_updated_at']:
        order_dict[oid] = order

orders = list(order_dict.values())

# Read customers.json
with open('/workspace/data/customers.json', 'r') as f:
    customers = json.load(f)

customer_map = {c['customer_id']: c for c in customers}

# Join customers
for order in orders:
    cust = customer_map.get(order['customer_id'])
    if cust:
        order['segment'] = cust['segment']
    else:
        order['segment'] = 'unknown'

# Read adjustments.csv
adjustments = {}
with open('/workspace/data/adjustments.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        adjustments[row['order_id']] = float(row['adjustment'])

# Apply adjustments
for order in orders:
    adj = adjustments.get(order['order_id'], 0)
    order['adjusted_amount'] = float(order['amount']) + adj

# Group by month and segment
groups = defaultdict(lambda: {'order_count': 0, 'total_amount': 0.0})
for order in orders:
    key = (order['month'], order['segment'])
    groups[key]['order_count'] += 1
    groups[key]['total_amount'] += order['adjusted_amount']

# Build result
result = []
for (month, segment), data in groups.items():
    result.append({
        'month': month,
        'segment': segment,
        'order_count': data['order_count'],
        'total_amount': round(data['total_amount'], 2)
    })

# Sort by month, then segment
result.sort(key=lambda x: (x['month'], x['segment']))

# Write output
with open('/workspace/outputs/report.json', 'w') as f:
    json.dump(result, f, indent=2)

print("Done!")
EOF"}

