{"cmd": "cat > /workspace/transform.py << 'EOF'
import json
import csv

# Load data
with open('/workspace/data/orders.json') as f:
    orders = json.load(f)

with open('/workspace/data/store_channels.csv') as f:
    reader = csv.DictReader(f)
    store_channels = {row['store_id'].strip(): row['channel'].strip().lower().capitalize() for row in reader}

with open('/workspace/data/order_adjustments.json') as f:
    adjustments = {adj['order_id']: adj['adjustment'] for adj in json.load(f)}

# 1. normalize_channels - add channel to each order
for order in orders:
    order['channel'] = store_channels.get(order['store_id'], 'Unknown')

# 2. filter_cancelled - remove cancelled orders
active_orders = [o for o in orders if o['status'].lower() != 'cancelled']

# 3. aggregate_status_counts - group by channel
channel_data = {}
for order in active_orders:
    channel = order['channel']
    status = order['status'].lower()
    if channel not in channel_data:
        channel_data[channel] = {'completed_orders': 0, 'processing_orders': 0, 'total_amount': 0.0}

    if status == 'completed':
        channel_data[channel]['completed_orders'] += 1
    elif status == 'processing':
        channel_data[channel]['processing_orders'] += 1

    channel_data[channel]['total_amount'] += order['amount']

# 4. apply_adjustments - apply adjustments to total amounts
for order in active_orders:
    if order['order_id'] in adjustments:
        channel = order['channel']
        channel_data[channel]['total_amount'] += adjustments[order['order_id']]

# Build output - sorted by channel
result = []
for channel in sorted(channel_data.keys()):
    data = channel_data[channel]
    result.append({
        'channel': channel,
        'completed_orders': data['completed_orders'],
        'processing_orders': data['processing_orders'],
        'total_amount': round(data['total_amount'], 2)
