import json
import csv

# Load data
with open('data/orders.json', 'r') as f:
    orders = json.load(f)

with open('data/store_channels.csv', 'r') as f:
    reader = csv.DictReader(f)
    store_channels = {row['store_id']: row['channel'].strip().lower() for row in reader}

with open('data/order_adjustments.json', 'r') as f:
    adjustments = {adj['order_id']: adj['adjustment'] for adj in json.load(f)}

# Create channel lookup map (normalize channel names)
channel_map = {}
for store_id, channel in store_channels.items():
    # Normalize: lowercase and strip whitespace
    normalized = channel.strip().lower()
    # Standardize channel names
    if normalized == 'retail':
        channel_map[store_id] = 'Retail'
    elif normalized == 'online':
        channel_map[store_id] = 'Online'
    elif normalized == 'partner':
        channel_map[store_id] = 'Partner'
    else:
        channel_map[store_id] = channel.title()

# Filter cancelled orders and normalize status
non_cancelled = []
for order in orders:
    status_lower = order['status'].lower()
    if status_lower != 'cancelled':
        non_cancelled.append(order)

# Aggregate by channel
channel_data = {}
for order in non_cancelled:
    store_id = order['store_id']
    channel = channel_map.get(store_id, 'Unknown')
    status = order['status'].lower()
    amount = order['amount']
    order_id = order['order_id']

    if channel not in channel_data:
        channel_data[channel] = {
            'completed_orders': 0,
            'processing_orders': 0,
            'total_amount': 0.0
        }

    if status == 'completed':
        channel_data[channel]['completed_orders'] += 1
    elif status == 'processing':
        channel_data[channel]['processing_orders'] += 1

    channel_data[channel]['total_amount'] += amount

# Apply adjustments
for order_id, adj in adjustments.items():
    # Find which order this belongs to
    for order in non_cancelled:
        if order['order_id'] == order_id:
            store_id = order['store_id']
            channel = channel_map.get(store_id, 'Unknown')
            channel_data[channel]['total_amount'] += adj
            break

# Build output sorted by channel
result = []
for channel in sorted(channel_data.keys()):
    data = channel_data[channel]
    result.append({
        'channel': channel,
        'completed_orders': data['completed_orders'],
        'processing_orders': data['processing_orders'],
        'total_amount': round(data['total_amount'], 2)
    })

# Write output
import os
os.makedirs('outputs', exist_ok=True)
with open('outputs/channel_pivot.json', 'w') as f:
    json.dump(result, f, indent=2)

print("Output written to outputs/channel_pivot.json")
print(json.dumps(result, indent=2))
EOF
